CREATE VIEW [dbo].[vwAssessorFeesHeader]
AS

SELECT 1 AS ID,'RICS' AS A, 'RICS Assessors' AS B,
CASE SUBSTRING(BatchDate,4,2)--CAST(DATEPART(mm,BatchDate)AS VARCHAR(4))
	WHEN '01' THEN 'Jan'
	WHEN '02' THEN 'Feb'
	WHEN '03' THEN 'Mar'
	WHEN '04' THEN 'Apr'
	WHEN '05' THEN 'May'
	WHEN '06' THEN 'Jun'
	WHEN '07' THEN 'Jul'
	WHEN '08' THEN 'Aug'
	WHEN '09' THEN 'Sep'
	WHEN '10' THEN 'Oct'
	WHEN '11' THEN 'Nov'
	WHEN '12' THEN 'Dec'
	END + ' ' +SUBSTRING(BatchDate,7,4) AS C    --CAST(YEAR(BatchDate)AS VARCHAR(4)) AS C --' 20' + SUBSTRING(@Period,LEN(@Period)-1,2) + ' SPR Pay and Expenses' AS C
, 'RICS Ass Fees ' +  
CASE SUBSTRING(BatchDate,4,2)  --CAST(DATEPART(mm,BatchDate)AS VARCHAR(4))
	WHEN '01' THEN 'Jan'
	WHEN '02' THEN 'Feb'
	WHEN '03' THEN 'Mar'
	WHEN '04' THEN 'Apr'
	WHEN '05' THEN 'May'
	WHEN '06' THEN 'Jun'
	WHEN '07' THEN 'Jul'
	WHEN '08' THEN 'Aug'
	WHEN '09' THEN 'Sep'
	WHEN '10' THEN 'Oct'
	WHEN '11' THEN 'Nov'
	WHEN '12' THEN 'Dec' 
	END + ' ' + SUBSTRING(BatchDate,7,4) AS D,--CAST(YEAR(BatchDate)AS VARCHAR(4)) AS D, 
	'dd/MM/yyyy' AS E,
	BatchDate
	FROM vwAssessorFees
UNION

SELECT 2 AS ID,NULL AS A, NULL AS B,NULL AS C, NULL AS D,NULL AS E, BatchDate
FROM vwAssessorFees

UNION 

SELECT 3 AS ID,'PLEASE NOTE THAT THE USE OF VLOOKUPS, FORMULAE AND THE LIKE IS NOT SUPPORTED BY THE UPLOAD AND IS NOT RECOMMENDED.' AS A,NULL AS B,NULL AS C, NULL AS D,NULL AS E, BatchDate
FROM vwAssessorFees

UNION

SELECT 4 AS ID, 'Q:IF THEY ARE USED IN A WORKSHEET THEN IT IS RECOMMENDED THAT THE DATA IS CUT AND PASTED AS VALUES BEFORE UPLOADING.' AS A,NULL AS B,NULL AS C, NULL AS D,NULL AS E, BatchDate
FROM vwAssessorFees
